  var PHRASE_TW_KEYS = null;
  function toTW(text) {
    if (!text || !/[一-鿿]/.test(text)) return text;
    /* 预翻译库（香港习惯用语）整句命中直接使用 */
    var tk = normKey(text);
    if (DB['zh-TW'] && DB['zh-TW'][tk]) return DB['zh-TW'][tk];
    if (!PHRASE_TW_KEYS) PHRASE_TW_KEYS = Object.keys(PHRASE_TW).sort(function (a, b) { return b.length - a.length; });
    /* 哨兵令牌法：先把短语级命中的部分替换成全角占位令牌（◆i◆），
       再做字符映射，最后还原短语——避免"公里/只有"等被 S2T 逐字误伤 */
    var temp = text, tokens = [];
    for (var i = 0; i < PHRASE_TW_KEYS.length; i++) {
      var p = PHRASE_TW_KEYS[i];
      if (temp.indexOf(p) >= 0) {
        var tok = '\u25c6' + i + '\u25c6';
        temp = temp.split(p).join(tok);
        tokens.push([tok, PHRASE_TW[p]]);
      }
    }
    temp = temp.replace(/[\u3400-\u9fff]/g, function (ch) { return S2T[ch] || ch; });
    for (var j = 0; j < tokens.length; j++) temp = temp.split(tokens[j][0]).join(tokens[j][1]);
    return temp;
  }

